int fd;
unsigned long operation_code;
void *argument_pointer;

// Generic usage
int result = ioctl(fd, operation_code, argument_pointer);

// Example: Get terminal settings (TCGETS)
struct termios settings;
ioctl(0, TCGETS, &settings);

// Example: Check input buffer size (FIONREAD)
int bytes_pending;
ioctl(fd, FIONREAD, &bytes_pending);
